<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#ABB2BF;"> rng.</span><span style="color:#61AFEF;">choice</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">self</span><span style="color:#ABB2BF;">.n_states, </span><span style="color:#E06C75;font-style:italic;">p</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">probs)</span></span>
