<span class="line"><span style="color:#C678DD;">        for</span><span style="color:#ABB2BF;"> _ </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(n_steps):</span></span>
